/**
 * Daily work reports.
 *
 * A report is generated by a normal Session: the Host aggregates the day's
 * board data into a fixed-format request, a model turns it into Markdown, and
 * the last assistant text is written atomically to `<dir>/<YYYY-MM-DD>.md`.
 * A 30s timer generates today's report once the configured local time passes.
 */
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  renameSync,
  statSync,
  writeFileSync,
} from 'node:fs'
import { join } from 'node:path'
import {
  DEFAULT_REPORT_TIME,
  HttpError,
  PRIORITY_LABELS,
  REPORT_DATE_PATTERN,
  REPORT_TIME_PATTERN,
} from './store.js'

const REPORT_TICK_MS = 30_000
const REPORT_POLL_MS = 1_000
const REPORT_MAX_WAIT_MS = 10 * 60 * 1000
const REPORT_LIST_LIMIT = 200
const FILE_PATTERN = /^\d{4}-\d{2}-\d{2}\.md$/

const STATUS_LABELS = {
  idea: '待开始',
  pending: '排队中',
  running: '执行中',
  paused: '已暂停',
  blocked: '阻塞',
  done: '已完成',
  failed: '失败',
  cancelled: '已取消',
}

function pad(value) {
  return String(value).padStart(2, '0')
}

/** Local calendar date, `YYYY-MM-DD`. */
export function localDateString(time = Date.now()) {
  const date = new Date(time)
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

/** Local wall-clock time, `HH:mm`. */
export function localTimeString(time = Date.now()) {
  const date = new Date(time)
  return `${pad(date.getHours())}:${pad(date.getMinutes())}`
}

/** [start, end) epoch bounds of one local calendar day; undefined if invalid. */
export function dayRange(date) {
  const text = String(date || '')
  if (!REPORT_DATE_PATTERN.test(text)) return undefined
  const [year, month, day] = text.split('-').map(Number)
  const start = new Date(year, month - 1, day).getTime()
  const check = new Date(start)
  if (check.getFullYear() !== year || check.getMonth() !== month - 1 || check.getDate() !== day) {
    return undefined
  }
  const end = new Date(year, month - 1, day + 1).getTime()
  return { start, end }
}

/**
 * The timer's due rule: enabled, the local time has passed, today has no
 * successful report yet, and no generation is in flight.
 */
export function isReportDue(settings, now = Date.now()) {
  if (!settings || settings.enabled !== true) return false
  const time = REPORT_TIME_PATTERN.test(String(settings.time || ''))
    ? settings.time
    : DEFAULT_REPORT_TIME
  if (localTimeString(now) < time) return false
  if (settings.lastDate === localDateString(now)) return false
  if (settings.generatingDate) return false
  return true
}

const REPORT_HEADING = /^# \d{4}-\d{2}-\d{2}/

/**
 * Extract exactly the report body from a model answer.
 *
 * The model sometimes narrates around its answer ("已生成并保存…") or echoes a
 * heading twice; only the first `# YYYY-MM-DD …` line onwards is the report.
 * When no heading exists the standard title is prepended. The result always
 * has trimmed trailing whitespace and exactly one trailing newline.
 */
export function extractReportBody(text, date) {
  const normalized = String(text || '').replace(/\r\n?/g, '\n')
  const lines = normalized.split('\n')
  let start = -1
  for (let index = 0; index < lines.length; index += 1) {
    if (REPORT_HEADING.test(lines[index].trim())) {
      start = index
      break
    }
  }
  let body
  if (start >= 0) {
    const heading = lines[start].trim()
    body = [heading, ...lines.slice(start + 1)].join('\n')
  } else {
    body = `# ${date} 工作日报\n\n${normalized}`
  }
  body = body.trimEnd()
  if (!body) body = `# ${date} 工作日报`
  return `${body}\n`
}

/** Backwards-compatible name: hosting writes the repaired body. */
export function ensureTitle(text, date) {
  return extractReportBody(text, date)
}

function truncate(text, limit) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim()
  return clean.length > limit ? `${clean.slice(0, limit)}…` : clean
}

function describeTask(task, limit = 240) {
  const status = STATUS_LABELS[task.status] || task.status
  const priority = PRIORITY_LABELS[task.priority] || PRIORITY_LABELS.normal
  const parts = [`[${status}] ${task.title}（优先级：${priority}）`]
  if (task.result && task.result.finalAnswer) parts.push(`结果：${truncate(task.result.finalAnswer, limit)}`)
  if (task.error) parts.push(`错误：${truncate(task.error, limit)}`)
  return parts.join('；')
}

/**
 * The fixed request. The four section headings must survive in the model
 * output; the Host repairs the title and strips narration afterwards.
 */
export function buildReportPrompt({ date, queueTasks, sessionTasks, ideas = [], unfinished }) {
  const queueLines = queueTasks.length
    ? queueTasks.map(task => `- ${describeTask(task)}`)
    : ['- 无']
  const sessionLines = sessionTasks.length
    ? sessionTasks.map(task => `- ${task.title}`)
    : ['- 无']
  const unfinishedLines = unfinished.length
    ? unfinished.map(task => `- ${describeTask(task)}`)
    : ['- 无']
  const ideaLines = ideas.length
    ? ideas.map(task => `- ${describeTask(task)}`)
    : ['- 无']
  return [
    `你是「任务管家」，请根据下面提供的 ${date} 当天数据，生成一份简洁、具体、只陈述事实的工作日报（简体中文 Markdown）。`,
    '',
    '要求：',
    `1. 只输出 Markdown 报告正文，第一行必须恰好是「# ${date} 工作日报」；正文前后不要添加任何说明、寒暄、复述或思考过程。`,
    '2. 不要调用任何工具，不要创建、写入或保存任何文件（文件由系统负责保存），不要解释过程。',
    '3. 必须严格使用以下结构，四个二级标题全部保留且顺序不变；不要输出代码块围栏，不要增加额外的一级标题。',
    '4. 只使用下面的数据，不要编造不存在的任务或结果；没有内容的分节写「无」。',
    '5. 每个条目用短句，可引用任务标题与结果要点；「明日计划」从进行中、未完成任务与待开始中的任务推导。',
    '6. 待开始中的任务尚未开始，不得计入「今日完成」，只能作为「明日计划」的候选。',
    '',
    '必须输出的结构：',
    '',
    `# ${date} 工作日报`,
    '',
    '## 一、今日完成',
    '',
    '## 二、进行中',
    '',
    '## 三、问题与阻塞',
    '',
    '## 四、明日计划',
    '',
    `今天是 ${date}。`,
    '',
    '当天队列任务（按看板顺序）：',
    ...queueLines,
    '',
    '当天 DSH 工作区会话：',
    ...sessionLines,
    '',
    '当前未完成的任务（含跨天）：',
    ...unfinishedLines,
    '',
    '待开始中暂不开展的任务（尚未开始）：',
    ...ideaLines,
  ].join('\n')
}

function errorMessage(error) {
  if (!error) return '未知错误'
  if (typeof error === 'string') return error
  if (typeof error.message === 'string' && error.message) return error.message
  try {
    return JSON.stringify(error)
  } catch {
    return String(error)
  }
}

function sleep(ms) {
  return new Promise(resolve => {
    const handle = setTimeout(resolve, ms)
    if (handle && typeof handle.unref === 'function') handle.unref()
  })
}

const SUMMARY_LIMIT = 42
const MAX_COMPLETED_BULLETS = 8
const MAX_PROGRESS_BULLETS = 8
const MAX_PLAN_BULLETS = 5

/** Flatten one task into a short, human-readable phrase (no technical detail). */
function briefTask(task, limit = SUMMARY_LIMIT) {
  const clean = value => String(value || '')
    .replace(/\r?\n+/g, ' ')
    .replace(/[#*_`>|]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
  let text = ''
  if (task.status === 'done') {
    text = clean(task.result && task.result.finalAnswer)
  } else if (task.status === 'failed') {
    text = clean(task.error)
  } else if (task.status === 'blocked') {
    text = clean(task.lastMessage) || '等待你的回答或审批'
  } else if (task.status === 'paused') {
    text = clean(task.lastMessage) || '已暂停，等待继续'
  } else if (task.status === 'running') {
    text = clean(task.lastMessage) || '正在处理'
  } else if (task.status === 'pending') {
    text = '等待领取'
  } else if (task.status === 'idea') {
    text = '暂未开始'
  }
  if (!text) text = '已完成'
  return text.length > limit ? `${text.slice(0, limit)}…` : text
}

function statusWord(status) {
  return {
    running: '执行中',
    paused: '已暂停',
    blocked: '阻塞',
    failed: '失败',
    pending: '排队中',
    idea: '待开始',
    done: '已完成',
    cancelled: '已取消',
  }[status] || status
}

function bulletLines(items, render, limit) {
  const shown = items.slice(0, limit)
  const lines = shown.map(item => `- ${render(item)}`)
  if (items.length > limit) lines.push(`- ……另有 ${items.length - limit} 项`)
  return lines
}

/**
 * Deterministic daily summary.
 *
 * The user asked for a *summary* of "what got done today and where it stands",
 * not a per-task transcript. The Host therefore assembles the fixed-format
 * report from the board itself — no model session, no latency, no invented
 * detail — and keeps every line short by construction.
 */
export function buildDailySummary(data) {
  const date = data.date
  const queueTasks = data.queueTasks || []
  const completed = queueTasks.filter(task => task.status === 'done')
  const failed = queueTasks.filter(task => task.status === 'failed')
  const unfinished = (data.unfinished || []).filter(task => task.source !== 'session')
  const running = unfinished.filter(task => task.status === 'running')
  const paused = unfinished.filter(task => task.status === 'paused')
  const blocked = unfinished.filter(task => task.status === 'blocked')
  const queued = unfinished.filter(task => task.status === 'pending')
  const ideas = (data.ideas || []).filter(task => task.status === 'idea')
  const sessions = data.sessionTasks || []

  const lines = [`# ${date} 工作日报`, '', '## 一、今日概览', '']
  const total = completed.length + running.length + paused.length + blocked.length + failed.length
  if (total === 0) {
    lines.push('今天没有队列任务进展。')
  } else {
    lines.push(`今日共 ${total} 项任务有进展：完成 ${completed.length} 项，进行中 ${running.length + paused.length} 项，阻塞 ${blocked.length} 项，失败 ${failed.length} 项。`)
    if (queued.length > 0) lines.push(`另有 ${queued.length} 项在排队等待执行。`)
  }
  if (sessions.length > 0) lines.push(`DSH 工作区有 ${sessions.length} 个会话今天有活动。`)
  if (ideas.length > 0) lines.push(`待开始（暂不开展）${ideas.length} 项。`)
  if (total === 0 && sessions.length === 0) lines.push('今天没有记录到任务活动。')

  lines.push('', '## 二、今日完成', '')
  if (completed.length > 0) {
    lines.push(...bulletLines(completed, task => `${task.title}：${briefTask(task)}`, MAX_COMPLETED_BULLETS))
  } else {
    lines.push('无')
  }

  lines.push('', '## 三、当前进展与问题', '')
  const progress = []
  for (const task of running) progress.push(`- ${task.title}（${statusWord(task.status)}）：${briefTask(task)}`)
  for (const task of paused) progress.push(`- ${task.title}（${statusWord(task.status)}）：${briefTask(task)}`)
  for (const task of blocked) progress.push(`- ${task.title}（${statusWord(task.status)}）：${briefTask(task)}`)
  for (const task of failed) progress.push(`- ${task.title}（失败）：${briefTask(task)}`)
  if (progress.length > 0) lines.push(...progress.slice(0, MAX_PROGRESS_BULLETS))
  else lines.push('无')
  if (progress.length > MAX_PROGRESS_BULLETS) lines.push(`- ……另有 ${progress.length - MAX_PROGRESS_BULLETS} 项`)

  lines.push('', '## 四、明日计划', '')
  const plan = []
  for (const task of running) plan.push(`- 继续推进：${task.title}`)
  for (const task of paused) plan.push(`- 恢复执行：${task.title}`)
  for (const task of blocked) plan.push(`- 解除阻塞：${task.title}`)
  for (const task of queued) plan.push(`- 安排执行：${task.title}`)
  for (const task of ideas) plan.push(`- 待开展：${task.title}`)
  if (plan.length > 0) lines.push(...plan.slice(0, MAX_PLAN_BULLETS))
  else lines.push('无')

  return `${lines.join('\n').replace(/\n{3,}/g, '\n\n').trim()}\n`
}

const AI_SUMMARY_MAX_CHARS = 1800
const AI_BULLET_LIMIT = 60
const AI_SECTION_BULLETS = { completed: 8, progress: 8, plan: 5 }

function compactLine(text, limit) {
  const clean = String(text || '')
    .replace(/\r?\n+/g, ' ')
    .replace(/[#*_`>|]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
  return clean.length > limit ? `${clean.slice(0, limit)}…` : clean
}

function technicalLine(line) {
  return /(token|tokens|耗时|模型|路径|优先级|会话\s*(id|ID)|cwd|provider)/i.test(line)
}

/**
 * Data for the AI summariser: short, human facts only. Long model answers are
 * reduced to one clause so the model summarises instead of copying.
 */
export function buildAiSummaryPrompt({ date, queueTasks = [], sessionTasks = [], ideas = [], unfinished = [] }) {
  const completed = queueTasks.filter(task => task.status === 'done')
  const failed = queueTasks.filter(task => task.status === 'failed')
  const queueUnfinished = unfinished.filter(task => task.source !== 'session')
  const running = queueUnfinished.filter(task => task.status === 'running')
  const paused = queueUnfinished.filter(task => task.status === 'paused')
  const blocked = queueUnfinished.filter(task => task.status === 'blocked')
  const queued = queueUnfinished.filter(task => task.status === 'pending')
  const lines = [
    `你是「任务管家」，请基于下面的板面数据，写一份**简洁的工作总结式日报**（简体中文 Markdown）。读者只想在 30 秒内知道：今天做了哪些任务、它们现在是什么进度/状态。`,
    '',
    '硬性要求：',
    `1. 只输出 Markdown 正文；第一行必须恰好是「# ${date} 工作日报」；不要寒暄、不要解释、不要输出代码块围栏。`,
    '2. 严格使用四个二级标题，文字与顺序都不能改：',
    '## 一、今日概览',
    '## 二、今日完成',
    '## 三、当前进展与问题',
    '## 四、明日计划',
    '3. 这是「总结」不是流水账：每项任务只占一行、每条不超过 40 字，格式「任务名：一句话进展或状态」；不要复述长结果、不要罗列原文、不要写 token、耗时、模型、路径、优先级、会话 ID 等技术细节。',
    '4. 「今日概览」用一段话给出数量（完成 X、进行中 Y、阻塞 Z、失败 W、排队 Q），可再用一句话概括整体进展。',
    '5. 「今日完成」只列今天真正完成的任务；「当前进展与问题」列进行中/暂停/阻塞/失败任务的当前状态或卡点；「明日计划」从进行中、阻塞、排队、待开始中提炼 1–3 条。',
    '6. 没有内容的分节写「无」；不要编造数据中不存在的内容；全文控制在 350 字以内。',
    '',
    `今天是 ${date}。数据如下：`,
    '',
    `概览数字：完成 ${completed.length} 项，进行中 ${running.length + paused.length} 项，阻塞 ${blocked.length} 项，失败 ${failed.length} 项，排队中 ${queued.length} 项，待开始 ${ideas.length} 项。`,
    '',
    '今日完成：',
    ...(completed.length
      ? completed.slice(0, 10).map(task => `- ${task.title}｜结果：${compactLine(task.result && task.result.finalAnswer, 60)}`)
      : ['- 无']),
    '',
    '当前进行中/暂停/阻塞/失败：',
    ...([...running, ...paused, ...blocked, ...failed].length
      ? [...running, ...paused, ...blocked, ...failed].slice(0, 12).map(task =>
        `- ${task.title}｜状态：${statusWord(task.status)}｜进展：${compactLine(task.status === 'failed' ? task.error : task.lastMessage, 60)}`)
      : ['- 无']),
    '',
    '排队中：',
    ...(queued.length ? queued.slice(0, 10).map(task => `- ${task.title}`) : ['- 无']),
    '',
    '待开始（暂不开展）：',
    ...(ideas.length ? ideas.slice(0, 10).map(task => `- ${task.title}`) : ['- 无']),
    '',
    `DSH 工作区会话：今天有 ${sessionTasks.length} 个会话活动${sessionTasks.length ? `（如 ${sessionTasks.slice(0, 3).map(task => compactLine(task.title, 24)).join('、')}）` : ''}。`,
  ]
  return lines.join('\n')
}

/**
 * Model output is normalised before writing: missing structure falls back to
 * the deterministic summary, over-long bullets are trimmed, technical lines
 * are dropped and each section is capped. The report stays a summary even when
 * the model is chatty.
 */
export function normalizeAiSummary(text, date, data) {
  const body = extractReportBody(text, date)
  const required = ['## 一、今日概览', '## 二、今日完成', '## 三、当前进展与问题', '## 四、明日计划']
  if (!required.every(heading => body.includes(heading))) {
    return { content: buildDailySummary({ date, ...data }), fallback: true }
  }
  const sections = []
  let current = null
  for (const raw of body.split('\n')) {
    const line = raw.replace(/\s+$/, '')
    const heading = required.find(item => line.trim() === item)
    if (heading) {
      current = { heading, lines: [] }
      sections.push(current)
      continue
    }
    if (!current) continue
    if (line.trim() === '') {
      if (current.lines.length > 0 && current.lines[current.lines.length - 1] !== '') current.lines.push('')
      continue
    }
    let value = line.trim()
    if (technicalLine(value)) continue
    const bullet = /^[-*+]\s+/.test(value)
    if (bullet) {
      const body = value.replace(/^[-*+]\s+/, '')
      if (body.trim() === '') continue
      value = `- ${compactLine(body, AI_BULLET_LIMIT)}`
    } else {
      // Only the overview may hold a prose paragraph; other sections are bullets.
      if (sections.length > 1) continue
      value = compactLine(value, 160)
    }
    current.lines.push(value)
  }
  const limits = [null, AI_SECTION_BULLETS.completed, AI_SECTION_BULLETS.progress, AI_SECTION_BULLETS.plan]
  const out = [`# ${date} 工作日报`, '']
  sections.forEach((section, index) => {
    const limit = limits[index]
    let bullets = 0
    const kept = []
    for (const line of section.lines) {
      if (line.startsWith('- ')) {
        bullets += 1
        if (limit && bullets > limit) continue
      }
      kept.push(line)
    }
    while (kept.length && kept[kept.length - 1] === '') kept.pop()
    if (kept.length === 0) kept.push('无')
    out.push(section.heading, '', ...kept, '')
  })
  let content = out.join('\n').replace(/\n{3,}/g, '\n\n').trim()
  if (content.length > AI_SUMMARY_MAX_CHARS) content = `${content.slice(0, AI_SUMMARY_MAX_CHARS).trimEnd()}…`
  return { content: `${content}\n`, fallback: false }
}

export function createReports({ ctx, store, bridge, notify, options = {} }) {
  const tickMs = Number.isFinite(options.tickMs) ? options.tickMs : REPORT_TICK_MS
  const pollMs = Number.isFinite(options.pollMs) ? options.pollMs : REPORT_POLL_MS
  const maxWaitMs = Number.isFinite(options.maxWaitMs) ? options.maxWaitMs : REPORT_MAX_WAIT_MS
  const push = typeof notify === 'function' ? notify : () => {}
  let timer = null
  let kickHandle = null
  let disposed = false

  function log(...args) {
    try {
      console.log('[personal-secretary]', ...args)
    } catch {
      // logging must never break report generation
    }
  }

  function settings() {
    return store.settings.dailyReport
  }

  function reportDir() {
    return settings().dir
  }

  function today() {
    return localDateString(Date.now())
  }

  function list() {
    const dir = reportDir()
    let names = []
    try {
      names = readdirSync(dir)
    } catch {
      return []
    }
    const reports = []
    for (const name of names) {
      if (!FILE_PATTERN.test(name)) continue
      const path = join(dir, name)
      try {
        const stat = statSync(path)
        if (!stat.isFile()) continue
        reports.push({
          date: name.slice(0, -3),
          path,
          bytes: stat.size,
          updatedAt: stat.mtimeMs,
        })
      } catch {
        // A file removed between readdir and stat is simply skipped.
      }
    }
    reports.sort((left, right) => (left.date < right.date ? 1 : left.date > right.date ? -1 : 0))
    return reports.slice(0, REPORT_LIST_LIMIT)
  }

  function read(date) {
    const text = String(date || '')
    if (!REPORT_DATE_PATTERN.test(text) || !dayRange(text)) {
      throw new HttpError(400, '日期格式应为 YYYY-MM-DD')
    }
    const path = join(reportDir(), `${text}.md`)
    if (!existsSync(path)) return undefined
    return readFileSync(path, 'utf8')
  }

  function meta() {
    return { reports: list(), settings: { ...settings() } }
  }

  function writeReportFile(date, content) {
    const dir = reportDir()
    mkdirSync(dir, { recursive: true })
    const target = join(dir, `${date}.md`)
    const tmp = join(dir, `.${date}.md.${process.pid}.${Date.now()}.tmp`)
    writeFileSync(tmp, content, 'utf8')
    renameSync(tmp, target)
    return target
  }

  function collectData(date) {
    const range = dayRange(date)
    if (!range) throw new HttpError(400, '日期无效')
    const inDay = time => Number.isFinite(time) && time >= range.start && time < range.end
    const queueTasks = []
    const sessionTasks = []
    for (const task of store.tasks) {
      if (task.source === 'session') {
        if (inDay(task.updatedAt || task.createdAt)) sessionTasks.push(task)
        continue
      }
      // The idea backlog is listed separately, never as today's queue work.
      if (task.status === 'idea') continue
      const stamp = Number.isFinite(task.endedAt) ? task.endedAt : (task.updatedAt || task.createdAt)
      if (inDay(stamp)) queueTasks.push(task)
    }
    const unfinished = store.tasks.filter(task =>
      task.status === 'pending' || task.status === 'running' ||
      task.status === 'paused' || task.status === 'blocked')
    // The idea column is a backlog, not a day-specific bucket: every pending
    // idea is listed so the plan section can draw on it.
    const ideas = store.tasks.filter(task => task.status === 'idea')
    return { queueTasks, sessionTasks, ideas, unfinished }
  }

  async function collect(date) {
    const dir = reportDir()
    mkdirSync(dir, { recursive: true })
    const data = collectData(date)
    const prompt = buildAiSummaryPrompt({ date, ...data })
    const sessionId = await bridge.createSession({ cwd: dir })
    // The report's Session is ours: it must not show up as a workspace import.
    store.ownSession(sessionId)
    await bridge.selectModel(sessionId, {
      provider: store.settings.provider,
      model: store.settings.model,
      reasoningEffort: store.settings.reasoningEffort,
    })
    const startedAt = Date.now()
    await bridge.prompt(sessionId, prompt)
    const deadline = startedAt + maxWaitMs
    for (;;) {
      if (disposed) throw new Error('日报生成已取消：插件已停止')
      const last = await bridge.lastTurnEnd(sessionId)
      if (last && last.reason) {
        const time = Number.isFinite(last.time) ? last.time : startedAt
        if (time >= startedAt - 1000) break
      }
      if (Date.now() >= deadline) throw new Error('日报生成超时（10 分钟）')
      await sleep(pollMs)
    }
    const summary = await bridge.summarize(sessionId)
    const text = String(summary.finalAnswer || '').trim()
    if (!text) {
      // An empty answer still produces a usable report from the board data.
      log('report model returned no content, using the local summary')
      return buildDailySummary({ date, ...data })
    }
    const normalized = normalizeAiSummary(text, date, data)
    if (normalized.fallback) log('report model output missed the fixed structure, using the local summary')
    return normalized.content
  }

  async function runGeneration(date) {
    try {
      const content = await collect(date)
      const reportPath = writeReportFile(date, content)
      store.updateDailyReport({
        lastDate: date,
        lastStatus: 'ok',
        lastError: null,
        lastGeneratedAt: Date.now(),
        generatingDate: null,
      })
      push('dailyReport', { date, content, path: reportPath })
    } catch (error) {
      log('report generation failed:', errorMessage(error))
      store.updateDailyReport({
        lastStatus: 'failed',
        lastError: errorMessage(error),
        generatingDate: null,
      })
    }
  }

  /**
   * Reserve the generation slot and start it in the background. The HTTP layer
   * and the timer both call this; a second call while one is in flight is a
   * conflict.
   */
  function generate(date) {
    const target = date === undefined || date === null || date === ''
      ? today()
      : String(date).trim()
    if (!REPORT_DATE_PATTERN.test(target) || !dayRange(target)) {
      throw new HttpError(400, '日期格式应为 YYYY-MM-DD')
    }
    if (settings().generatingDate) throw new HttpError(409, '日报正在生成中')
    store.updateDailyReport({ generatingDate: target, lastStatus: 'running', lastError: null })
    void runGeneration(target)
    return { ok: true, date: target }
  }

  async function checkDue(now = Date.now()) {
    try {
      if (disposed) return
      if (!isReportDue(settings(), now)) return
      generate(localDateString(now))
    } catch (error) {
      log('report due check failed:', errorMessage(error))
    }
  }

  function recoverStale() {
    const current = settings()
    if (current.lastStatus === 'running' || current.generatingDate) {
      store.updateDailyReport({
        lastStatus: 'failed',
        lastError: '上次日报生成未完成（进程已重启）',
        generatingDate: null,
      })
    }
  }

  function start() {
    if (timer || disposed) return
    recoverStale()
    timer = setInterval(() => { void checkDue() }, tickMs)
    if (typeof timer === 'object' && timer && typeof timer.unref === 'function') timer.unref()
    void checkDue()
  }

  function stop() {
    disposed = true
    if (timer) clearInterval(timer)
    timer = null
    if (kickHandle) clearTimeout(kickHandle)
    kickHandle = null
  }

  /** Immediate re-check after the settings row changed. */
  function kick() {
    if (disposed) return
    if (kickHandle) return
    kickHandle = setTimeout(() => {
      kickHandle = null
      void checkDue()
    }, 50)
    if (kickHandle && typeof kickHandle.unref === 'function') kickHandle.unref()
  }

  recoverStale()

  return {
    start,
    stop,
    kick,
    list,
    read,
    meta,
    today,
    generate,
    checkDue,
    recoverStale,
    reportDir,
    isGenerating: () => Boolean(settings().generatingDate),
  }
}

export {
  REPORT_TICK_MS,
  REPORT_POLL_MS,
  REPORT_MAX_WAIT_MS,
  REPORT_LIST_LIMIT,
  STATUS_LABELS,
}
